// Las reglas de «Cargas del Sur» (inventadas) escritas en la capa de aplicación.
export const MAX_PENDIENTES = 2;
const TARIFA_KG = 1200, TARIFA_BULTO = 300, MINIMO = 2500, RECARGO_TARDE = 0.20;

// R1: tarifa = kilos y bultos, mínimo facturable y recargo por ventana de la tarde
export function calcularTarifa({ pesoG, bultos, ventana }) {
  let t = (pesoG / 1000) * TARIFA_KG + bultos * TARIFA_BULTO;
  if (ventana === 'tarde') t *= 1 + RECARGO_TARDE;
  return Math.max(MINIMO, Math.round(t));
}

// R3: como mucho 2 envíos pendientes por cliente
export async function crearEnvio(db, clienteId, e) {
  const { rows } = await db.query("select count(*)::int as n from envios where cliente_id = $1 and estado = 'pendiente'", [clienteId]);
  if (rows[0].n >= MAX_PENDIENTES) throw new Error('demasiados_pendientes');
  const tarifa = calcularTarifa(e);
  const r = await db.query('insert into envios (cliente_id, destino, peso_g, bultos, ventana, tarifa) values ($1,$2,$3,$4,$5,$6) returning id',
    [clienteId, e.destino, e.pesoG, e.bultos, e.ventana, tarifa]);
  return r.rows[0].id;
}

// R2: solo se cancela un envío pendiente
export async function cancelarEnvio(db, id) {
  const { rows } = await db.query('select estado from envios where id = $1', [id]);
  if (!rows.length) throw new Error('no_existe');
  if (rows[0].estado !== 'pendiente') throw new Error('no_se_puede_cancelar');
  await db.query("update envios set estado = 'cancelado' where id = $1", [id]);
}

-- R3: como mucho 2 envíos pendientes por cliente, también cuando llegan a la vez
create function limite_pendientes() returns trigger language plpgsql as $$
begin
  perform pg_advisory_xact_lock(new.cliente_id);   -- los pedidos del mismo cliente hacen fila
  if (select count(*) from envios where cliente_id = new.cliente_id and estado = 'pendiente') >= 2 then
    raise exception 'demasiados_pendientes';
  end if;
  return new;
end $$;
create trigger envios_limite before insert on envios
  for each row execute function limite_pendientes();

-- R2: un envío en ruta o entregado no se cancela, venga de donde venga el UPDATE
create function transicion_valida() returns trigger language plpgsql as $$
begin
  if new.estado = 'cancelado' and old.estado <> 'pendiente' then
    raise exception 'no_se_puede_cancelar';
  end if;
  return new;
end $$;
create trigger envios_transicion before update of estado on envios
  for each row execute function transicion_valida();

// El mismo comportamiento, pero dentro del objeto (modelo rico). Sin base de datos.
const TARIFA_KG = 1200, TARIFA_BULTO = 300, MINIMO = 2500, RECARGO_TARDE = 0.20;

export class Envio {
  #estado = 'pendiente';
  constructor({ pesoG, bultos, ventana }) {
    if (!Number.isInteger(pesoG) || pesoG < 1) throw new Error('peso_invalido');
    if (!Number.isInteger(bultos) || bultos < 1) throw new Error('bultos_invalidos');
    if (ventana !== 'manana' && ventana !== 'tarde') throw new Error('ventana_invalida');
    Object.assign(this, { pesoG, bultos, ventana });
  }
  get estado() { return this.#estado; }
  tarifa() {
    let t = (this.pesoG / 1000) * TARIFA_KG + this.bultos * TARIFA_BULTO;
    if (this.ventana === 'tarde') t *= 1 + RECARGO_TARDE;
    return Math.max(MINIMO, Math.round(t));
  }
  despachar() { if (this.#estado !== 'pendiente') throw new Error('no_se_puede_despachar'); this.#estado = 'en_ruta'; }
  cancelar() { if (this.#estado !== 'pendiente') throw new Error('no_se_puede_cancelar'); this.#estado = 'cancelado'; }
}

import { test } from 'node:test';
import assert from 'node:assert/strict';
import { Envio } from './dominio.mjs';

test('mínimo facturable', () => assert.equal(new Envio({ pesoG: 500, bultos: 1, ventana: 'manana' }).tarifa(), 2500));
test('recargo de la tarde', () => {
  const m = new Envio({ pesoG: 10000, bultos: 2, ventana: 'manana' }).tarifa();
  const t = new Envio({ pesoG: 10000, bultos: 2, ventana: 'tarde' }).tarifa();
  assert.equal(m, 12600); assert.equal(t, 15120);
});
test('un envío en ruta no se cancela', () => {
  const e = new Envio({ pesoG: 5000, bultos: 1, ventana: 'manana' });
  e.despachar();
  assert.throws(() => e.cancelar(), /no_se_puede_cancelar/);
});
test('no existe un envío de cero gramos', () => assert.throws(() => new Envio({ pesoG: 0, bultos: 1, ventana: 'manana' }), /peso_invalido/));
